using System.Collections.Generic;
using Godot;
using Strata.Core.Content;
using Strata.Game.Items;

namespace Strata.Game.UI;

/// <summary>
/// Terraria-style pixel sprites for the HUD and inventory (hearts, stars, bubbles, the defence shield, trash, empty-slot
/// silhouettes, buttons, the pointer, hints and frames), generated by tools/textures/build_ui.py into
/// res://assets/ui/&lt;name&gt;.png. Each map cell is 2x2 pixels with a 1 px dark outline, so draw them at their own size
/// or an integral multiple; a control that scales one sets <c>TextureFilter = Nearest</c>. A missing sprite is reported
/// once and drawn as the magenta "missing" texture so the gap is visible.
/// </summary>
public static class UiSprites
{
    /// <summary>Every sprite the game draws; the HUD loads them all when it initialises so no frame waits on the disk.</summary>
    public static readonly string[] Preloaded =
    {
        "heart", "heart_gold", "star", "bubble", "shield", "trash", "favourite_star",
        "slot_head", "slot_body", "slot_legs", "slot_accessory", "slot_dye", "slot_pet", "slot_light_pet",
        "slot_minecart", "slot_mount", "slot_hook", "slot_coin", "slot_ammo",
        "eye_open", "eye_closed", "sort", "quick_stack", "deposit", "loot", "reforge_hammer", "toggle_on", "toggle_off",
        "tab_equipment", "tab_misc", "cursor", "smart_cursor", "talk_hint", "open_hint", "minimap_frame",
    };

    private static readonly Dictionary<string, Texture2D> Cache = new();

    /// <summary>Sprites asked for that have no file, each counted (and warned about) once.</summary>
    public static int MissingCount { get; private set; }

    public static int LoadedCount => Cache.Count - MissingCount;

    public static string PathFor(string name) => "res://" + AssetPaths.UiSprite(name);

    public static Texture2D Get(string name)
    {
        if (Cache.TryGetValue(name, out var tex)) return tex;
        var path = PathFor(name);
        if (ResourceLoader.Exists(path))
        {
            tex = GD.Load<Texture2D>(path);
        }
        else
        {
            GD.PushWarning($"Missing UI sprite '{name}' ({path}); run tools/textures/build_ui.py.");
            MissingCount++;
            tex = ItemIcons.MissingTexture;
        }
        Cache[name] = tex;
        return tex;
    }

    /// <summary>Loads every <see cref="Preloaded"/> sprite (cached, so later calls cost nothing).</summary>
    public static void Preload()
    {
        foreach (var name in Preloaded) Get(name);
    }
}
